<?php
$formatScore = static function ($score): string {
    $formatted = number_format((float) $score, 1, ',', '.');
    return str_ends_with($formatted, ',0') ? substr($formatted, 0, -2) : $formatted;
};
$rankFor = static function (float $score): string {
    return $score >= 90 ? 'Peringkat 1' : ($score >= 80 ? 'Peringkat 2' : ($score >= 70 ? 'Peringkat 3' : ($score >= 60 ? 'Peringkat 4' : 'Tidak Terakreditasi')));
};
